export async function handleEvent(event, dependencies) {
  throw new Error('Implement the idempotent handler');
}

import assert from 'node:assert/strict';
import { handleEvent } from './handler.js';

const processed = new Set();
const created = [];
const dependencies = {
  processed,
  orders: {
    async create(order) {
      created.push(order);
    }
  }
};

const event = { id: 'evt-1001', data: { orderId: 'ord-42', total: 125 } };
assert.deepEqual(await handleEvent(event, dependencies), { duplicate: false });
assert.equal(created.length, 1);
assert.equal(processed.has('evt-1001'), true);
assert.deepEqual(await handleEvent(event, dependencies), { duplicate: true });
assert.equal(created.length, 1);
await assert.rejects(() => handleEvent({ data: {} }, dependencies), /event id/i);
console.log('6 assertions passed');
